from PIL import Image
import numpy as np
im=np.array(Image.open('mol_0021.png').convert('L'))
b=(im<128)
def scan_cols(x0,x1,y0,y1,label):
    print('---',label)
    for j in range(x0,x1):
        ys=[i for i in range(y0,y1) if b[i,j]]
        groups=[]
        for y in ys:
            if groups and y-groups[-1][-1]<=2: groups[-1].append(y)
            else: groups.append([y])
        print(j,[(g[0],g[-1],g[-1]-g[0]+1) for g in groups])
scan_cols(336,380,60,105,'A-H bond')
